# ==============================================================================
# 3. PUBLICATION THEME
# ==============================================================================

theme_manuscript <- function(
    base_size = 11
) {
  
  theme_bw(
    base_size = base_size
  ) +
    
    theme(
      
      plot.title =
        element_text(
          face = "bold",
          size = base_size + 2
        ),
      
      plot.subtitle =
        element_text(
          size = base_size
        ),
      
      strip.text =
        element_text(
          face = "bold"
        ),
      
      panel.grid.minor =
        element_blank(),
      
      legend.title =
        element_text(
          face = "bold"
        ),
      
      plot.margin =
        margin(
          8,
          8,
          8,
          8
        )
    )
}


# ==============================================================================
# 4. HELPERS
# ==============================================================================

clean_sample_id <- function(x) {
  
  x <- toupper(
    trimws(
      as.character(x)
    )
  )
  
  x <- gsub(
    "[^A-Z0-9]",
    "",
    x
  )
  
  return(x)
}


z_safe <- function(x) {
  
  x <- as.numeric(x)
  
  s <- stats::sd(
    x,
    na.rm = TRUE
  )
  
  if (
    !is.finite(s) ||
    s == 0
  ) {
    
    return(
      rep(
        NA_real_,
        length(x)
      )
    )
  }
  
  return(
    as.numeric(
      scale(x)
    )
  )
}


save_publication_plot <- function(
    plot_object,
    filename_stub,
    width,
    height
) {
  
  png_file <- file.path(
    figures_dir,
    paste0(
      filename_stub,
      ".png"
    )
  )
  
  pdf_file <- file.path(
    figures_dir,
    paste0(
      filename_stub,
      ".pdf"
    )
  )
  
  tiff_file <- file.path(
    figures_dir,
    paste0(
      filename_stub,
      ".tiff"
    )
  )
  
  
  ggsave(
    filename = png_file,
    plot = plot_object,
    width = width,
    height = height,
    dpi = 600
  )
  
  ggsave(
    filename = pdf_file,
    plot = plot_object,
    width = width,
    height = height
  )
  
  ggsave(
    filename = tiff_file,
    plot = plot_object,
    width = width,
    height = height,
    dpi = 600,
    compression = "lzw"
  )
  
  return(
    invisible(
      c(
        png_file,
        pdf_file,
        tiff_file
      )
    )
  )
}


