selected_signature_columns <- c(
  "primary_5gene_score",
  "LIFTS_like",
  "FAIM3_PLAC8_like",
  "Sepsis_MetaScore_like"
)


selected_signature_names <- c(
  "primary_5gene_score" = "Primary 5-gene",
  "LIFTS_like" = "LIFTS-like",
  "FAIM3_PLAC8_like" = "FAIM3:PLAC8-like",
  "Sepsis_MetaScore_like" = "Sepsis MetaScore-like"
)


trajectory_data <- benchmark_scores137 %>%
  
  filter(
    grepl(
      "^BP[0-9]+$",
      sample_id
    )
  ) %>%
  
  select(
    sample_id,
    CTS,
    all_of(
      selected_signature_columns
    )
  ) %>%
  
  pivot_longer(
    cols =
      all_of(
        selected_signature_columns
      ),
    
    names_to =
      "score_column",
    
    values_to =
      "score"
  ) %>%
  
  group_by(
    score_column
  ) %>%
  
  mutate(
    score_z =
      z_safe(
        score
      )
  ) %>%
  
  ungroup() %>%
  
  mutate(
    
    display_name =
      unname(
        selected_signature_names[
          score_column
        ]
      ),
    
    CTS =
      factor(
        CTS,
        levels = c(
          "CTS1",
          "CTS2",
          "CTS3"
        )
      )
  )


trajectory_summary <- trajectory_data %>%
  
  group_by(
    display_name,
    CTS
  ) %>%
  
  summarise(
    
    median_score =
      median(
        score_z,
        na.rm = TRUE
      ),
    
    q1 =
      quantile(
        score_z,
        0.25,
        na.rm = TRUE
      ),
    
    q3 =
      quantile(
        score_z,
        0.75,
        na.rm = TRUE
      ),
    
    .groups =
      "drop"
  )


p5d <- ggplot(
  trajectory_summary,
  aes(
    x = CTS,
    y = median_score,
    group = display_name,
    color = display_name
  )
) +
  
  geom_line(
    linewidth = 1.0
  ) +
  
  geom_point(
    size = 3
  ) +
  
  geom_errorbar(
    aes(
      ymin = q1,
      ymax = q3
    ),
    width = 0.08,
    linewidth = 0.6
  ) +
  
  scale_color_manual(
    values =
      signature_colors
  ) +
  
  labs(
    title =
      "D  Convergent CTS trajectories",
    
    subtitle =
      "Median standardized score with interquartile range",
    
    x =
      "Consensus Transcriptomic Subtype",
    
    y =
      "Standardized signature score",
    
    color =
      "Signature"
  ) +
  
  theme_manuscript(
    base_size = 9
  ) +
  
  theme(
    legend.position = "bottom"
  )


