    ),
    width = 0.15,
    orientation = "y"
  ) +
  
  geom_point(
    size = 3.5
  ) +
  
  geom_vline(
    xintercept = 0.5,
    linetype = 2
  ) +
  
  scale_color_manual(
    values =
      signature_colors
  ) +
  
  coord_cartesian(
    xlim = c(
      0.45,
      1.02
    )
  ) +
  
  labs(
    title =
      "Supplementary Figure S2. Contextual BP-versus-BC biomarker benchmarking",
    
    subtitle =
      paste0(
        "Sepsis versus healthy controls; apparent AUC only. ",
        "This is not independent diagnostic validation."
      ),
    
    x =
      "AUC",
    
    y =
      NULL
  ) +
  
  theme_manuscript() +
  
  theme(
    legend.position = "none"
  )


save_publication_plot(
  plot_object =
