# ==============================================================================
# 35. SUPPLEMENTARY FIGURE S4
# ALL SIGNATURES ACROSS CTS
# ==============================================================================

all_signature_columns <- c(
  "primary_5gene_score",
  "DCAF17_alt_score",
  "SeptiCyte_LAB_like",
  "SeptiCyte_RAPID_like",
  "FAIM3_PLAC8_like",
  "Sepsis_MetaScore_like",
  "LIFTS_like"
)


all_signature_names <- c(
  "primary_5gene_score" = "Primary 5-gene",
  "DCAF17_alt_score" = "DCAF17 alternative",
  "SeptiCyte_LAB_like" = "SeptiCyte LAB-like",
  "SeptiCyte_RAPID_like" = "PLAC8-PLA2G7 contrast",
  "FAIM3_PLAC8_like" = "FAIM3:PLAC8-like",
  "Sepsis_MetaScore_like" = "Sepsis MetaScore-like",
  "LIFTS_like" = "LIFTS-like"
)


s4_data <- benchmark_scores137 %>%
  
  filter(
    grepl(
      "^BP[0-9]+$",
      sample_id
    )
  ) %>%
  
  select(
    sample_id,
    CTS,
    all_of(
      all_signature_columns
    )
  ) %>%
  
  pivot_longer(
    cols =
      all_of(
        all_signature_columns
      ),
    
    names_to =
      "score_column",
    
    values_to =
      "score"
  ) %>%
  
  group_by(
    score_column
  ) %>%
  
  mutate(
    score_z =
      z_safe(
        score
      )
  ) %>%
  
  ungroup() %>%
  
  mutate(
    
    display_name =
      unname(
        all_signature_names[
          score_column
        ]
      ),
    
    CTS =
      factor(
        CTS,
        levels = c(
          "CTS1",
          "CTS2",
          "CTS3"
        )
      )
  )


figure_s4 <- ggplot(
  s4_data,
  aes(
    x = CTS,
    y = score_z,
    fill = CTS
  )
) +
  
  geom_boxplot(
    outlier.shape = NA,
    alpha = 0.65
  ) +
  
  geom_jitter(
    aes(
      color = CTS
    ),
    width = 0.10,
    size = 1.2
  ) +
  
  facet_wrap(
    ~ display_name,
    ncol = 3
  ) +
  
  scale_fill_manual(
    values =
      cts_colors
  ) +
  
  scale_color_manual(
    values =
      cts_colors
  ) +
  
  labs(
    title =
      "Supplementary Figure S4. Blood biomarker signatures across CTS classes",
    
    subtitle =
      "Scores standardized within the sepsis cohort",
    
    x =
      "Consensus Transcriptomic Subtype",
    
    y =
      "Standardized score"
  ) +
  
  theme_manuscript(
    base_size = 8
  ) +
  
  theme(
    legend.position = "none"
  )


save_publication_plot(
  plot_object =
    figure_s4,
  
  filename_stub =
    "138_Supplementary_Figure_S4_all_signatures_CTS",
  
  width =
    12,
  
  height =
    9
)


